using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);

// Log to stderr only — stdout is reserved for the JSON-RPC protocol
builder.Logging.AddConsole(options =>
    options.LogToStandardErrorThreshold = LogLevel.Trace);

// Register HttpClient via DI so tools can receive it through constructor injection
builder.Services.AddHttpClient();

builder.Services.AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();

using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private const string BaseUrl = "https://jsonplaceholder.typicode.com";

    [McpServerTool, Description("Get a user by their numeric ID from the REST API.")]
    public async Task<string> GetUser(
        [Description("The numeric user ID (1-10)")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching user {UserId}", userId);
        var response = await httpClient.GetStringAsync(
            $"{BaseUrl}/users/{userId}", cancellationToken);
        return response;
    }

    [McpServerTool, Description("List all posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Optional user ID to filter posts by author")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var url = userId.HasValue
            ? $"{BaseUrl}/posts?userId={userId.Value}"
            : $"{BaseUrl}/posts";

        logger.LogInformation("Fetching posts from {Url}", url);
        var response = await httpClient.GetStringAsync(url, cancellationToken);

        // Return a summary to keep responses concise for the LLM
        using var doc = JsonDocument.Parse(response);
        var posts = doc.RootElement.EnumerateArray()
            .Select(p => new
            {
                id = p.GetProperty("id").GetInt32(),
                title = p.GetProperty("title").GetString()
            });

        return JsonSerializer.Serialize(posts, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerTool(ReadOnly = true), Description("Get a specific post by its ID.")]
    public async Task<string> GetPost(
        [Description("The numeric post ID")] int postId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {PostId}", postId);
        var response = await httpClient.GetStringAsync(
            $"{BaseUrl}/posts/{postId}", cancellationToken);
        return response;
    }
}

